import jakarta.validation.*;
import jakarta.validation.constraints.*;
import java.util.*;

// 会員登録フォーム(画面の入力欄と1対1のクラス)
// ここを変えてみよう:注釈の数値やメッセージを変える、@Pattern を足してみる
class MemberForm {
    @NotBlank(message = "名前を入力してください")
    @Size(max = 20, message = "名前は20文字以内です")
    String name;

    @NotBlank(message = "メールを入力してください")
    @Email(message = "メールの形式が正しくありません")
    String email;

    @NotNull(message = "年齢を入力してください")
    @Min(value = 18, message = "18歳以上が対象です")
    @Max(value = 120, message = "年齢が大きすぎます")
    Integer age;

    MemberForm(String name, String email, Integer age) {
        this.name = name; this.email = email; this.age = age;
    }
}

Validator validator = Validation.buildDefaultValidatorFactory().getValidator();

void check(MemberForm form) {
    Set<ConstraintViolation<MemberForm>> errors = validator.validate(form);
    System.out.println("--- " + form.name + " / " + form.email + " / " + form.age);
    if (errors.isEmpty()) { System.out.println("OK!"); return; }
    errors.stream()   // Set は順番が決まらないので項目名で並べる
        .sorted(Comparator.comparing(v -> v.getPropertyPath().toString()))
        .forEach(v -> System.out.println(v.getPropertyPath() + ": " + v.getMessage()));
}

// ここを変えてみよう:値を書き換えて、どの注釈に引っかかるか見る
check(new MemberForm("山田太郎", "taro@example.com", 30));
check(new MemberForm("   ", "taro", 17));
check(new MemberForm("あ".repeat(21), "", null));

import jakarta.validation.constraints.*;
import org.springframework.beans.MutablePropertyValues;
import org.springframework.validation.*;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import java.util.*;

// @ModelAttribute の裏側で Spring がやっていること(バインド → 検証 → BindingResult)を手で再現する
public class SignupForm {
    @NotBlank(message = "氏名を入力してください")
    private String name;
    @NotNull(message = "年齢を入力してください")
    @Min(value = 18, message = "18歳以上が対象です")
    private Integer age;
    @NotBlank(message = "パスワードを入力してください")
    private String password;
    private String passwordConfirm;

    // 相関チェック:passwordMatched という項目として検証される
    @AssertTrue(message = "確認用パスワードが一致しません")
    public boolean isPasswordMatched() {
        return password != null && password.equals(passwordConfirm);
    }

    public String getName() { return name; }
    public void setName(String v) { name = v; }
    public Integer getAge() { return age; }
    public void setAge(Integer v) { age = v; }
    public String getPassword() { return password; }
    public void setPassword(String v) { password = v; }
    public String getPasswordConfirm() { return passwordConfirm; }
    public void setPasswordConfirm(String v) { passwordConfirm = v; }
}

LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
validator.afterPropertiesSet();

// ブラウザから届いたリクエストパラメータ(すべて文字列)のつもり
// ここを変えてみよう:age を "" や "20" に、passwordConfirm を "secret1" にする
Map<String, String> params = new LinkedHashMap<>();
params.put("name", "山田太郎");
params.put("age", "abc");
params.put("password", "secret1");
params.put("passwordConfirm", "secret2");

SignupForm form = new SignupForm();
DataBinder binder = new DataBinder(form, "signupForm");
binder.setValidator(validator);
binder.bind(new MutablePropertyValues(params)); // 名前が同じプロパティに setter で詰める
binder.validate();                              // @Validated の正体
BindingResult result = binder.getBindingResult();

// DB を見ないと分からないチェックは、自分でエラーを足す(Service で重複を見つけた想定)
if ("山田太郎".equals(form.getName())) {
    result.rejectValue("name", "duplicate", "その氏名は登録済みです");
}

System.out.println("エラー件数: " + result.getErrorCount());
List<FieldError> errors = new ArrayList<>(result.getFieldErrors());
errors.sort(Comparator.comparing(FieldError::getField));
for (FieldError e : errors) {
    String msg = "typeMismatch".equals(e.getCode())
            ? "数値で入力してください" : e.getDefaultMessage();
    System.out.println(e.getField() + " [" + e.getCode() + "] 入力値="
            + e.getRejectedValue() + " → " + msg);
}
System.out.println("form.getAge() = " + form.getAge() + "(変換できない値はセットされない)");

import jakarta.validation.constraints.*;
import org.springframework.stereotype.Controller;
import org.springframework.validation.BindingResult;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

public class MemberForm {
    @NotBlank(message = "氏名を入力してください")
    private String name;
    @NotBlank(message = "メールを入力してください")
    @Email(message = "メールの形式が正しくありません")
    private String email;
    public String getName() { return name; }
    public void setName(String v) { name = v; }
    public String getEmail() { return email; }
    public void setEmail(String v) { email = v; }
}

@Controller
public class MemberController {
    int count = 0; // 登録件数(本物は Service → Repository に任せる)

    // ここを変えてみよう:@Validated を消すと? BindingResult の引数と if 文を消すと?
    @PostMapping("/members")
    public String register(@Validated @ModelAttribute MemberForm form,
                           BindingResult result,
                           RedirectAttributes ra) {
        if (result.hasErrors()) {
            return "members/form";            // 同じ画面(入力値とエラーつき)
        }
        count++;
        ra.addFlashAttribute("message", "登録しました");
        return "redirect:/members/done";      // PRG
    }
}

LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
validator.afterPropertiesSet();
MemberController controller = new MemberController();
MockMvc mvc = MockMvcBuilders.standaloneSetup(controller)
        .setValidator(validator).build();

void send(String name, String email) throws Exception {
    MvcResult r = mvc.perform(post("/members")
            .param("name", name).param("email", email)).andReturn();
    System.out.println("--- name=" + name + " email=" + email);
    System.out.println("ステータス: " + r.getResponse().getStatus());
    if (r.getModelAndView() != null) {
        System.out.println("ビュー名: " + r.getModelAndView().getViewName());
        BindingResult br = (BindingResult) r.getModelAndView().getModel()
                .get(BindingResult.MODEL_KEY_PREFIX + "memberForm");
        if (br != null) {
            br.getFieldErrors().stream()
                .sorted(Comparator.comparing(e -> e.getField()))
                .forEach(e -> System.out.println(
                    "  エラー " + e.getField() + ": " + e.getDefaultMessage()));
        }
    }
    System.out.println("リダイレクト先: " + r.getResponse().getRedirectedUrl());
    System.out.println("フラッシュ属性 message: "
            + r.getFlashMap().get("message"));
}

// ここを変えてみよう:いろいろな入力で送ってみる
send("山田太郎", "taro@example.com");
send("", "taro");
System.out.println("登録件数: " + controller.count);

